import{_ as o,l as s,o as e,c as l,v as t,p as n,x as i,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const V=JSON.parse('{"title":"半虚拟化","description":"","frontmatter":{"title":"半虚拟化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/paravirtualization.md","filePath":"cs/paravirtualization.md","lastUpdated":1789023840000}'),c={name:"cs/paravirtualization.md"};function v(u,a,_,f,m,E){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="半虚拟化" tabindex="-1">半虚拟化 <a class="header-anchor" href="#半虚拟化" aria-label="Permalink to &quot;半虚拟化&quot;">​</a></h1><div class="epigraph"><p>半虚拟化让客户知道自己在 VM 里：用 hypercall 或 virtio 环替代模拟遗留设备，从而少 VM-exit、少模拟税。</p><footer>—— 据 Barham et al., Xen；Russell, virtio；[KVM/QEMU](/cs/kvm-qemu) 为先修</footer></div><p><a href="/cs/shadow-page-table">EPT</a> 解决 MMU。<a href="/cs/vmx-vmexit">VM-exit</a> 仍会被模拟网卡打爆。缺口是 <strong>virtio/xen PV</strong>：客户驱动配合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模拟 e1000：每发包 PIO/MMIO exit。virtio：共享环、kick 可用 eventfd，批量。缺口：virtio-net/blk/fs；与 <a href="/cs/sendfile-splice">sendfile</a> 在客户内仍有效。本课不把 virtio 规范全章抄来。</p><p><span class="marginnote">启蒙（enlightenment）是 Windows 用语。对象是知情客户，不是类型 1 专属。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户装 virtio 驱动 → 发现 PCI virtio 设备 → 环与 QEMU/vhost 通信。vhost：部分数据面进宿主内核，少到用户。对照 <a href="/cs/bridge-tun-tap">tun</a>：tap 仍常是后端。对照 XDP：宿主可对 tap 再加速。</p>',8)),(e(),n(h,null,{default:i(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GDRV%5B%22%E5%AE%A2%E6%88%B7%20virtio%20%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20RING%5B%22%E5%85%B1%E4%BA%AB%E7%8E%AF%22%5D%0A%20%20RING%20--%3E%20VHOST%5B%22vhost%20%E6%88%96%20QEMU%22%5D%0A%20%20VHOST%20--%3E%20TAP%5B%22tap%2F%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>半虚拟把设备模型从「精确模拟硬件」换成「为 VM 设计的 ABI」，性能接近直通的一部分，可迁移性更好。不要写成云网卡型号。与 <a href="/cs/scsi-stack">SCSI</a>：virtio-blk 绕过客户 SCSI 模拟。</p><p>无 PV 驱动则掉进慢模拟。</p><p>实现上：vhost-net 在宿主内核消费 virtio 环，QEMU 只处理控制面。无 PV 驱动时海量 exit 模拟 e1000。virtio-fs 用 FUSE 协议过环，语义接近本地但不是。 读法上只引用<a href="/cs/shadow-page-table">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>半虚拟化</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 virtio 特性位。不保证 GPU 半虚拟的完整。下一课硬件级：SR-IOV 与直通。</p><p>版本字段会变，课序钉的是机制对象「半虚拟化」，不是某一主线内核的结构体名。 后课默认：知情客户可用环 I/O。把物理函数切成虚拟函数，下一课 SR-IOV。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半虚拟用 hypercall/virtio 减少模拟。</li><li>vhost 把数据面放进宿主内核。</li><li>SR-IOV 直通是下一课。</li><li>出处：Xen；virtio；KVM vhost。</li></ul>',11))])}const S=o(c,[["render",v]]);export{V as __pageData,S as default};
